Required packages
Some packages from the CRAN are required to run the examples on this website.
Download the script 001_required_packages.R, or copy the codes below into your own script.


 Download script



Install packages

# Install packages
# installed from BiocManager ---------------------------------------------------

if (!requireNamespace("BiocManager", quietly = TRUE))
  install.packages("BiocManager")

# decontam
if (!require("decontam", quietly = TRUE))
  BiocManager::install("decontam")

# phyloseq
if (!require("phyloseq", quietly = TRUE))
  BiocManager::install("phyloseq")

# CRAN packages ----------------------------------------------------------------

if (!require("ggplot2", quietly = TRUE))
  install.packages("ggplot2")

if (!require("ggpubr", quietly = TRUE))
  install.packages("ggpubr")

if (!require("vegan", quietly = TRUE))
  install.packages("vegan")

if (!require("openxlsx", quietly = TRUE))
  install.packages("openxlsx")

if (!require("plyr", quietly = TRUE))
  install.packages("plyr")

if (!require("dplyr", quietly = TRUE))
  install.packages("dplyr")



Load packages

# Load packages
library(decontam)
library(phyloseq)
library(ggplot2)
library(ggpubr)
library(vegan)
library(openxlsx)
library(plyr)
library(dplyr) # always load dplyr last to avoid conflicts between packages



Homemade functions
Some additional functions used in this workflow are not part of any R package. These functions are listed below. Make sure to add them to your scripts!

# Homemade functions -----------------------------------------------------------

# Remove taxa from phyloseq objects
remove_taxa &lt;- function(badTaxa, physeq){
  allTaxa &lt;- taxa_names(physeq)
  cleanTaxa &lt;- allTaxa[!(allTaxa %in% badTaxa)]
  return(prune_taxa(cleanTaxa, physeq))
}

# Merge 10 best hits
mergeHits &lt;- function(BLAST10, sp = 98.7, ge = 94.5, fa = 86.5, or = 82,
                      cl = 78.5, ph = 75, ki = 70){

  BLAST10_merge &lt;- BLAST10 %&gt;%
    # Replace NA with character string "NA"
    mutate(across(phylum:species, function(x) if_else(is.na(x), "NA", x))) %&gt;% 
    # Split into a list of data frames
    group_split(OTU)

  # Loop through the list of data frames
  for (i in 1:length(BLAST10_merge)){

    # Assign NULL to variables without binding
    best.species &lt;- best.genus &lt;- best.family &lt;- best.order &lt;- 
      best.class &lt;- best.phylum &lt;- NULL

    # Frequency of species
    species &lt;- as.data.frame(table(BLAST10_merge[[i]]$species)) %&gt;%
      `colnames&lt;-`(c("species", "freq")) %&gt;% 
      mutate(species = as.character(species))

    sp.lim &lt;- sp/100*nrow(BLAST10_merge[[i]])

    if(max(species$freq) &gt;= sp.lim){
      best.species &lt;- species$species[[which(species$freq &gt;= sp.lim)]]
    }
    if(isTRUE(best.species != "NA")){
      BLAST10_merge[[i]] &lt;- BLAST10_merge[[i]] %&gt;%
        filter(species == best.species) %&gt;%
        arrange(desc(pident)) %&gt;% .[1,]
    } else {

      # Frequency of genus
      genus &lt;- as.data.frame(table(BLAST10_merge[[i]]$genus)) %&gt;%
        `colnames&lt;-`(c("genus", "freq")) %&gt;% 
        mutate(genus = as.character(genus))

      ge.lim &lt;- ge/100*nrow(BLAST10_merge[[i]])

      if(max(genus$freq) &gt;= ge.lim){
        best.genus &lt;- genus$genus[[which(genus$freq &gt;= ge.lim)]]
      }
      if(isTRUE(best.genus != "NA")){
        BLAST10_merge[[i]] &lt;- BLAST10_merge[[i]] %&gt;%
          filter(genus == best.genus) %&gt;%
          arrange(desc(pident)) %&gt;% .[1,] %&gt;%
          mutate(species = NA)
      } else {

        # Frequency of family
        family &lt;- as.data.frame(table(BLAST10_merge[[i]]$family)) %&gt;%
          `colnames&lt;-`(c("family", "freq")) %&gt;% 
          mutate(family = as.character(family))

        fa.lim &lt;- fa/100*nrow(BLAST10_merge[[i]])

        if(max(family$freq) &gt;= fa.lim){
          best.family &lt;- family$family[[which(family$freq &gt;= fa.lim)]]
        }
        if(isTRUE(best.family != "NA")){
          BLAST10_merge[[i]] &lt;- BLAST10_merge[[i]] %&gt;%
            filter(family == best.family) %&gt;%
            arrange(desc(pident)) %&gt;% .[1,] %&gt;%
            mutate(species = NA, genus = NA)
        } else {

          # Frequency of order
          order &lt;- as.data.frame(table(BLAST10_merge[[i]]$order)) %&gt;%
            `colnames&lt;-`(c("order", "freq")) %&gt;% 
            mutate(order = as.character(order))

          or.lim &lt;- or/100*nrow(BLAST10_merge[[i]])

          if(max(order$freq) &gt;= or.lim){
            best.order &lt;- order$order[[which(order$freq &gt;= or.lim)]]
          }
          if(isTRUE(best.order != "NA")){
            BLAST10_merge[[i]] &lt;- BLAST10_merge[[i]] %&gt;%
              filter(order == best.order) %&gt;%
              arrange(desc(pident)) %&gt;% .[1,] %&gt;%
              mutate(species = NA, genus = NA, family = NA)
          } else {

            # Frequency of class
            class &lt;- as.data.frame(table(BLAST10_merge[[i]]$class)) %&gt;%
              `colnames&lt;-`(c("class", "freq")) %&gt;% 
              mutate(class = as.character(class))

            cl.lim &lt;- cl/100*nrow(BLAST10_merge[[i]])

            if(max(class$freq) &gt;= cl.lim){
              best.class &lt;- class$class[[which(class$freq &gt;= cl.lim)]]
            }
            if(isTRUE(best.class != "NA")){
              BLAST10_merge[[i]] &lt;- BLAST10_merge[[i]] %&gt;%
                filter(class == best.class) %&gt;%
                arrange(desc(pident)) %&gt;% .[1,] %&gt;%
                mutate(species = NA, genus = NA, family = NA, order = NA)
            } else {

              # Frequency of phylum
              phylum &lt;- as.data.frame(table(BLAST10_merge[[i]]$phylum)) %&gt;%
                `colnames&lt;-`(c("phylum", "freq")) %&gt;% 
                mutate(phylum = as.character(phylum))

              ph.lim &lt;- ph/100*nrow(BLAST10_merge[[i]])

              if(max(phylum$freq) &gt;= ph.lim){
                best.phylum &lt;- phylum$phylum[[which(phylum$freq &gt;= ph.lim)]]
              }
              if(isTRUE(best.phylum != "NA")){
                BLAST10_merge[[i]] &lt;- BLAST10_merge[[i]] %&gt;%
                  filter(phylum == best.phylum) %&gt;%
                  arrange(desc(pident)) %&gt;% .[1,] %&gt;%
                  mutate(species = NA, genus = NA, family = NA, order = NA, class = NA)
              } else {

                # Frequency of kingdom
                kingdom &lt;- as.data.frame(table(BLAST10_merge[[i]]$kingdom)) %&gt;%
                  `colnames&lt;-`(c("kingdom", "freq")) %&gt;% 
                  mutate(kingdom = as.character(kingdom))

                ki.lim &lt;- ki/100*nrow(BLAST10_merge[[i]])

                if(max(kingdom$freq) &gt;= ki.lim){
                  best.kingdom &lt;- kingdom$kingdom[[which(kingdom$freq &gt;= ki.lim)]]
                }
                if(isTRUE(best.kingdom != "NA")){
                  BLAST10_merge[[i]] &lt;- BLAST10_merge[[i]] %&gt;%
                    filter(kingdom == best.kingdom) %&gt;%
                    arrange(desc(pident)) %&gt;% .[1,] %&gt;%
                    mutate(species = NA, genus = NA, family = NA, order = NA, 
                           class = NA, phylum = NA)
                }
              }
            }
          }
        }
      }
    }
  }

  BLAST10_merge &lt;- BLAST10_merge %&gt;% map_df(~as.data.frame(.x))

  return(BLAST10_merge)
}
